add('10_002','巨大脚掌接触碎石地的特写，脚趾占下中前景，小腿从上中央垂下，碎石四周飞起。',['巨大的脚掌','小腿局部','碎石'],['脚掌踩压碎石','碎石飞起'],['趾端有小块硬甲','脚掌压在地面'],'碎石地与近处灰暗空层',[],'Action，脚掌从地面上方短落至源接触，碎石飞起后下落；只一落脚无追击。',['脚掌贴近碎石面',['脚掌压落','碎石从接触处短飞'],'落脚实际兑现，随后接局部束缚','脚掌已经压在石地上'],'本段不开战斗模块，落脚只用源接触最短前导；不推导人物受击。',3,['70mm贴地低角度脚掌特写，巨大脚趾占下中前景，小腿由上中央垂下，四周碎石围住接触区；固定机位，趾端和石块层次分开。','巨大的脚掌向下短落，脚趾压进碎石面，石块沿两侧跳起。趾端硬甲擦过碎石，脚掌沉稳承住重量，飞起的小石逐块落低，脚仍压在石地上。','背景为灰褐碎石地，石块有尖角和深褐裂缝，较远处灰暗石面低亮。','无台词。','左上柔光照出脚掌灰橄榄大块面，趾下阴影冷暗，飞起碎石的边缘有浅灰亮面。','一声重而短的落脚闷响，碎石接连碰撞落下，尾部有细碎砂砾声。'],flags=['G'],bgmode='physical')
DATA[-1]['admissions']=[{'claim':'脚掌向下短落并踩压碎石','visual_evidence':'源脚掌压地、石块飞起和竖向速度线；最短落脚前导不改变接触结果'}]
add('11_001','横向脚掌近景占中央前景，趾端向左，踝部出右缘，白色弧纹绕局部；碎石在后。',['巨大的脚掌局部','白色环纹','碎石'],['白色环纹环绕脚掌'],['脚掌压着碎石','环纹围住脚掌'],'后方大块尖角碎石及低亮灰面',[],'Action，脚压地持续，白亮环纹从已见局部起流并收束；不补施法者或攻击方向。',['脚掌压着碎石',['白色环纹绕局部铺开','环纹向脚缘收束'],'能力局部结果在脚掌上出现','脚掌仍压地，环纹收弱'],'与10_002落脚连贯；原图提高仍无法孤立判断掌/足，只按相邻已见落脚拓扑处理，未新增关节或手指。',3,['75mm平视横向脚掌近景，脚掌占中央前景，趾端朝左，踝部延出右缘，白亮弧纹环绕表面；尖角碎石在后景。固定机位。','巨大脚掌继续压着碎石，几道冷白环纹沿露出的表面迅速绕过。亮纹在趾侧和踝侧交错收束，脚掌绷紧一点，趾端仍贴在石块间；环纹的亮度逐渐收弱。','后方背景为灰褐尖角碎石，缝隙深褐黑，上方灰暗空层简化而低亮。','无台词。','冷白环纹照亮脚缘和石块尖角，脚面灰橄榄块面清楚，石缝保持冷暗。','连续细亮气流声绕过，碎石轻磨，末段亮声逐渐收细。'],flags=['G'],bgmode='physical')
